{
  "name": "@dylanrussell/chezmoi-guard",
  "version": "2.1.0",
  "description": "Native OpenCode V2 guard: block managed target mutations, guide explicit source edits, and preserve host permission checks.",
  "license": "MIT",
  "author": "Dylan Russell",
  "type": "module",
  "main": "./dist/plugin.js",
  "module": "./dist/plugin.js",
  "types": "./dist/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "tui.mjs",
    "README.md",
    "CHANGELOG.md",
    "SECURITY.md",
    "LICENSE"
  ],
  "homepage": "https://github.com/dylanrussellmd/opencode-chezmoi-guard#readme",
  "bugs": "https://github.com/dylanrussellmd/opencode-chezmoi-guard/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dylanrussellmd/opencode-chezmoi-guard.git"
  },
  "scripts": {
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "lint": "biome check src tests",
    "lint:fix": "biome check --write src tests",
    "format": "biome format --write src tests",
    "test": "vitest run --coverage",
    "test:unit": "vitest run tests/unit",
    "test:integration": "npm run build && node scripts/integration-smoke.mjs",
    "test:watch": "vitest",
    "version": "node scripts/sync-version.mjs && git add src/version.ts",
    "prepublishOnly": "npm run lint && npm run typecheck && npm run build && npm run test"
  },
  "peerDependencies": {
    "@opencode/plugin": "2.0.8 || 2.0.19"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@biomejs/biome": "^1.9.4",
    "@opencode/plugin": "2.0.19",
    "@types/node": "^20.14.0",
    "@vitest/coverage-v8": "^4.1.11",
    "tsup": "^8.5.1",
    "tsx": "^4.21.0",
    "typescript": "^5.6.0",
    "vitest": "^4.1.11"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "chezmoi",
    "dotfiles",
    "file-manager",
    "guard"
  ],
  "publishConfig": {
    "access": "public"
  },
  "overrides": {
    "esbuild": "^0.28.1",
    "postcss": "^8.5.23",
    "nanoid@3": "^3.3.18",
    "@opentelemetry/core": "^2.8.0"
  },
  "pnpm": {
    "overrides": {
      "uuid": ">=14.0.0",
      "vite": ">=6.4.2",
      "esbuild": ">=0.25.0"
    }
  }
}
